(()=>{const url=new URL(location.href);const requested=url.searchParams.get('lang');const current=location.pathname.endsWith('/en.html')?'en':'uk';let preferred;try{preferred=localStorage.getItem('cutline-language');}catch{}const selected=requested==='en'||requested==='uk'?requested:preferred;const explicit=location.pathname.endsWith('/en.html')||location.pathname.endsWith('/index.html');if((requested||!explicit)&&selected&&selected!==current){url.pathname=url.pathname.replace(/[^/]*$/,selected==='en'?'en.html':'index.html');url.searchParams.delete('lang');location.replace(url.href);return;}document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('.language-switch a').forEach(link=>link.addEventListener('click',()=>{try{localStorage.setItem('cutline-language',link.lang);}catch{}const target=new URL(link.href);target.hash=location.hash;link.href=target.href;}));});})();
